<script setup>
import { CheckCircle2, X } from 'lucide-vue-next'
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
onMounted(() => { const timer = window.setInterval(() => { const page = document.querySelector('.tracking-page'); if (!page || order.value?.estado !== 'ENTREGADO' || page.querySelector('.delivered-center-confirmation')) return; const confirmation = document.createElement('section'); confirmation.className = 'delivered-center-confirmation'; confirmation.innerHTML = '<div class="delivered-center-check">✓</div><h1>¡Pedido entregado!</h1><p>Tu pedido fue entregado correctamente.</p>'; page.append(confirmation) }, 100); onBeforeUnmount(() => window.clearInterval(timer)) })
import { useRoute, useRouter } from 'vue-router'
import { cancelOrder, getOrder } from '../services/orderService'
import { getDrivingRoute } from '../services/routeService'
import { supabase } from '../lib/supabase'
import CourierRequestMap from '../components/CourierRequestMap.vue'
import OrderTrackingSheet from '../components/OrderTrackingSheet.vue'
import CancelOrderModal from '../components/CancelOrderModal.vue'
import '../assets/tracking-cancel.css'
const route = useRoute(); const router = useRouter(); const order = ref(null); const routeInfo = ref(null); const error = ref(''); const connected = ref(true); const cancelOpen = ref(false); const cancelling = ref(false); let channels = []
onMounted(() => { const timer = window.setInterval(() => { const confirmation = document.querySelector('.tracking-confirmation'); if (confirmation) confirmation.style.display = order.value?.estado === 'ENTREGADO' ? 'none' : '' }, 100); onBeforeUnmount(() => window.clearInterval(timer)) })
function point(source, lat, lon) { const a = Number(source?.[lat]); const b = Number(source?.[lon]); return Number.isFinite(a) && Number.isFinite(b) ? [a, b] : null }
function formatTime(date, includePeriod = true) { const formatter = new Intl.DateTimeFormat('es-SV', { timeZone: 'America/El_Salvador', hour: 'numeric', minute: '2-digit', hour12: true }); const parts = formatter.formatToParts(date); const hour = parts.find((part) => part.type === 'hour')?.value; const minute = parts.find((part) => part.type === 'minute')?.value; const period = parts.find((part) => part.type === 'dayPeriod')?.value || ''; return includePeriod ? `${hour}:${minute} ${period}` : `${hour}:${minute}` }
async function refreshDeliveryEstimate() { if (!order.value || !['ASIGNADO', 'RECOGIDO', 'EN_CAMINO'].includes(order.value.estado)) return; const restaurant = point(order.value.restaurantes, 'pos_y', 'pos_x'); const destination = point(order.value.direcciones, 'latitud', 'longitud'); const courier = point(order.value.repartidor_ubicacion, 'pos_y', 'pos_x') || restaurant; if (!destination || !courier) return; try { let minutes = 0; if (order.value.estado === 'ASIGNADO' && restaurant) { const toRestaurant = await getDrivingRoute(courier, restaurant); const toClient = await getDrivingRoute(restaurant, destination); minutes = ((toRestaurant?.duration || 0) + (toClient?.duration || 0)) / 60 } else { const toClient = await getDrivingRoute(courier, destination); minutes = (toClient?.duration || 0) / 60 } if (!minutes) return; const now = new Date(); const eta = new Date(now.getTime() + Math.ceil(minutes) * 60000); const start = new Date(Math.max(now.getTime(), eta.getTime() - 5 * 60000)); const end = new Date(eta.getTime() + 5 * 60000); routeInfo.value = { ...(routeInfo.value || {}), min: minutes, window: `${formatTime(start, false)} - ${formatTime(end)}` } } catch { /* El mapa conserva su estado aunque OSRM no responda. */ } }
const assignment = computed(() => (order.value?.asignaciones || []).find((item) => !item.terminada_en) || null); const hasCourier = computed(() => order.value?.estado !== 'CANCELADO' && Boolean(assignment.value)); const showMap = computed(() => order.value?.estado !== 'CANCELADO' && Boolean(assignment.value)); const restaurant = computed(() => order.value?.restaurantes); const courier = computed(() => order.value?.repartidor_ubicacion || assignment.value?.repartidores); const destination = computed(() => order.value?.direcciones ? { latitud: order.value.direcciones.latitud, longitud: order.value.direcciones.longitud, detalle: order.value.direcciones.detalle, zonas: order.value.direcciones.zonas } : null)
async function load() { try { order.value = await getOrder(route.params.id); await refreshDeliveryEstimate(); window.setTimeout(refreshDeliveryEstimate, 700); if (!channels.length) subscribe() } catch (e) { error.value = e.message || 'No se pudo cargar la confirmación.' } }
async function refreshFromRealtime() { try { const next = await getOrder(route.params.id); if (next) { order.value = next; await refreshDeliveryEstimate(); window.setTimeout(refreshDeliveryEstimate, 700) } } catch (e) { error.value = e.message || 'No se pudo actualizar el seguimiento.' } }
function stopTracking() { channels.forEach((channel) => supabase.removeChannel(channel)); channels = []; routeInfo.value = null }
const cancellationReasons = { SIN_REPARTIDORES_EN_AREA: 'No hay repartidores suficientes en el área', SIN_REPARTIDORES: 'No hay repartidores suficientes en el área', CAPACIDAD_SUPERADA: 'La capacidad de repartidores fue superada', ZONA_BLOQUEADA: 'La zona se encuentra bloqueada', RESTAURANTE_RECHAZA: 'El restaurante rechazó el pedido', PRODUCTOS_NO_DISPONIBLES: 'Productos no disponibles', PROBLEMAS_DE_ENTREGA: 'Problemas de entrega', SOLICITUD_CLIENTE: 'Solicitud del cliente', CAMBIO_DE_OPINION: 'Cambio de opinión', ERROR_EN_PEDIDO: 'Error en el pedido', DIRECCION_INCORRECTA: 'Dirección incorrecta', DEMORA_EN_PEDIDO: 'Demora en el pedido', OTRO: 'Otro' }
function cancellationReason(code, description) { if (cancellationReasons[code]) return cancellationReasons[code]; if (description?.trim()) return description.trim(); if (code) return code.replaceAll('_', ' ').toLowerCase().replace(/^./, (letter) => letter.toUpperCase()); return 'Motivo no especificado' }
function refundMessage(refund, paymentState) { if (paymentState === 'CANCELADO_SIN_COBRO') return 'No hubo ningún cobro y no se generó devolución.'; if (!refund) return 'No hay una devolución asociada.'; if (refund.estado === 'SIMULADO_COMPLETADO') return `Devolución completada por $${Number(refund.monto || 0).toFixed(2)}.`; if (refund.estado === 'REVISION_MANUAL') return 'La devolución está pendiente de revisión administrativa.'; if (refund.estado === 'REVISION_APROBADA') return 'La devolución fue aprobada; todavía no se registra como dinero devuelto.'; if (refund.estado === 'REVISION_RECHAZADA') return 'La solicitud de devolución fue rechazada.'; return 'La devolución está pendiente de procesamiento.' }
function subscribe() { const orderChannel = supabase.channel(`order-${route.params.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'pedidos', filter: `id=eq.${route.params.id}` }, async ({ new: next }) => { order.value = { ...order.value, ...next }; await refreshFromRealtime(); if (order.value.estado === 'CANCELADO' || order.value.estado === 'ENTREGADO') stopTracking() }).on('system', {}, () => { connected.value = false }).subscribe((status) => { connected.value = status === 'SUBSCRIBED' }); const assignmentChannel = supabase.channel(`assignment-${route.params.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'asignaciones', filter: `pedido_id=eq.${route.params.id}` }, refreshFromRealtime).subscribe(); channels = [orderChannel, assignmentChannel] }
async function cancelClientOrder({ motivo, descripcion }) { cancelling.value = true; error.value = ''; try { const result = await cancelOrder(order.value.id, motivo, descripcion); if (result?.duplicado) { await load(); } else { await refreshFromRealtime(); stopTracking() }; cancelOpen.value = false } catch (e) { const message = e?.message || ''; error.value = message.includes('CANCELACION_NO_AUTORIZADA') ? 'El pedido ya fue aceptado y ya no puede cancelarse desde el cliente.' : message.includes('DESCRIPCION_REQUERIDA') ? 'La descripción es obligatoria para este motivo.' : message || 'No se pudo cancelar el pedido.' } finally { cancelling.value = false } }
onMounted(load); onBeforeUnmount(stopTracking)
</script>
<template><main class="tracking-page" :class="{ 'tracking-page--map': showMap }"><div v-if="!showMap" class="tracking-confirmation"><div class="success-check"><CheckCircle2 :size="62" /></div><h1>{{ order?.estado === 'CANCELADO' ? 'Pedido cancelado' : '¡Pedido realizado!' }}</h1><p>{{ order?.estado === 'CANCELADO' ? 'Tu pedido fue cancelado y se conservó en tu historial.' : 'Tu pedido fue registrado correctamente.' }}</p><p v-if="order?.estado === 'CANCELADO' && order.cancelaciones?.[0]" class="tracking-cancellation-detail">Motivo: {{ cancellationReason(order.cancelaciones[0].motivo_codigo, order.cancelaciones[0].descripcion) }}<span v-if="order.cancelaciones[0].descripcion"> · {{ order.cancelaciones[0].descripcion }}</span></p><p v-if="order?.estado === 'CANCELADO'" class="tracking-cancellation-detail">Método: {{ order.metodo_pago === 'TARJETA_SIMULADA' ? 'Tarjeta simulada' : 'Efectivo' }} · Total: ${{ Number(order.total || 0).toFixed(2) }}</p><p v-if="order?.estado === 'CANCELADO'" class="tracking-cancellation-detail">{{ refundMessage(order.reembolsos?.[0], order.estado_pago) }}</p></div><CourierRequestMap v-else :restaurant="restaurant" :destination="destination" :courier="courier" :state="order.estado" @route="routeInfo = $event" /><p v-if="error" class="checkout-error tracking-error">{{ error }}</p><OrderTrackingSheet v-if="order" :order="order" :has-courier="hasCourier" :route-info="routeInfo" @back="router.push('/')" /><button v-if="order?.estado === 'PENDIENTE_ACEPTACION'" class="tracking-cancel-button" type="button" @click="cancelOpen = true">Cancelar pedido</button><button class="tracking-exit" aria-label="Salir del seguimiento" @click="router.push('/cliente')"><X :size="18" /> Salir del seguimiento</button><CancelOrderModal v-model="cancelOpen" role="client" :order="order" :busy="cancelling" @close="cancelOpen = false" @confirm="cancelClientOrder" /></main></template>
